-- 0008: extra properties as bookable units (booked whole, confirmed straight away; Donald is told), real property
-- details, indicative prices (app_settings), and iCal
-- import/export so dates booked on Airbnb / Booking.com / freetobook block Roomboard and the other way round.
-- Not deployed yet: needs Donald's approval. Data section generated by scripts/gen-sql-data.mjs.

-- ---------- columns ----------
alter table properties add column if not exists details jsonb not null default '{}';
alter table rooms add column if not exists details jsonb not null default '{}';
-- Who made a booking. Extras: Sheena sees and changes only her own; Donald's other bookings reach her as dates only.
alter table stays add column if not exists booked_by uuid default auth.uid();
-- Activity Sheena must not see (Donald's own extra-property bookings, calendar clashes).
alter table activity add column if not exists manager_only boolean not null default false;
drop policy if exists "activity read" on activity;
create policy "activity read" on activity for select using (my_role() = 'manager' or (my_role() = 'client' and not manager_only));
create or replace function log_activity_private(r text, msg text, ent text default null, ent_id text default null) returns void
language sql security definer set search_path = public as $$
  insert into activity (property_id, entity, entity_id, text, manager_only) select property_id, ent, ent_id, msg, true from rooms where id = r $$;

-- ---------- Donald's settings: the indicative rate (£ per room per week) ----------
-- Everyone signed in reads it; only the manager changes it. Shown everywhere as "Indicative £350 per room per week".
create table if not exists app_settings (key text primary key, value jsonb not null, updated_at timestamptz not null default now());
insert into app_settings (key, value) values ('rate_per_room_week', '350') on conflict (key) do nothing;
alter table app_settings enable row level security;
create policy "settings read" on app_settings for select using (auth.uid() is not null);
create policy "settings manager" on app_settings for update using (my_role() = 'manager') with check (my_role() = 'manager'
  and key = 'rate_per_room_week' and jsonb_typeof(value) = 'number' and (value #>> '{}')::numeric between 1 and 100000);
-- Every change of a setting, kept for Donald: who, when, old and new value. Written by the trigger only.
create table if not exists app_settings_history (id bigserial primary key, key text not null, old_value jsonb,
  new_value jsonb not null, changed_by uuid, changed_at timestamptz not null default now());
alter table app_settings_history enable row level security;
create policy "settings history manager" on app_settings_history for select using (my_role() = 'manager');
create or replace function app_settings_log() returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.updated_at := now();
  if new.value is distinct from old.value then
    insert into app_settings_history (key, old_value, new_value, changed_by) values (new.key, old.value, new.value, auth.uid());
  end if;
  return new;
end $$;
drop trigger if exists app_settings_log on app_settings;
create trigger app_settings_log before update on app_settings for each row execute function app_settings_log();
-- Indicative price of a booking: weekly ÷ 7 per night. Extras are whole-property: their charged rooms (details.charged,
-- else every bedroom; Abhainn Cottage 2 of 3) are priced.
create or replace function indicative_price(r text, a date, d date) returns text language sql stable security definer set search_path = public as $$
  select case when d is null
    then 'Indicative £' || to_char(w, 'FM999,999') || ' per week, until further notice'
    else 'Indicative £' || to_char(round(w / 7.0 * (d - a)), 'FM999,999') || ' for ' || (d - a) || ' night' || case when d - a = 1 then '' else 's' end
         || ' (£' || to_char(w, 'FM999,999') || ' a week ÷ 7 × ' || (d - a) || ')' end
  from (select (select (value #>> '{}')::numeric from app_settings where key = 'rate_per_room_week')
               * case when p.contracted then 1 else coalesce((p.details->>'charged')::int, (p.details->>'bedrooms')::int, 1) end as w
        from rooms rm join properties p on p.id = rm.property_id where rm.id = r) x $$;

