insert into properties (id,name,short_name,contracted,address,blurb,photo_url,features,beds_label,brand,checkout_time,checkin_time,sort,details) values ('p-pod1','Harris','Harris',false,'2A Breasclete, Isle of Lewis HS2 9ED','Harris View: a self-catering pod in an elevated spot in Breasclete, with views of the mountains of Lewis and Harris. One bedroom and a pull-out sofa bed, an en-suite with a powerful electric shower, a kitchenette and a dining table for four.','img/pod-exterior.webp',array['En-suite shower','Kitchenette','Free Wi-Fi','Off-road parking','TV','Decking','Linen & towels']::text[],'1 bedroom + sofa bed','Hebridean Holiday Cabins','10:00','16:00',3,'{"area":"Breasclete, Isle of Lewis","photos":[{"src":"img/pod-exterior.webp","alt":"A Hebridean Holiday Cabins pod"},{"src":"img/pod-inside.webp","alt":"Inside the pod: sofa, bed and kitchenette"},{"src":"img/pod-bed.webp","alt":"Bedroom"},{"src":"img/pod-kitchen.webp","alt":"Kitchenette and dining table"},{"src":"img/pod-shower.webp","alt":"En-suite shower room"},{"src":"img/pod-view.webp","alt":"View from the pod door"}],"sleeps":"2 adults + 2 children","bedrooms":1,"website":"https://hebrideanholidaycabins.co.uk/accommodation/","bookingUrl":"https://booking-directly.com/widgets/AFdwunTlQtRXLGG59glXBg6bzyX2zGOL7uVYq3BXiXjQVNUL0wvLZtXa9p9Fd/properties","credit":"Photos and details: hebrideanholidaycabins.co.uk (the two pods are the same design; photos may show either)"}'::jsonb)
