delete from rooms where id = 'x-lodge' and not exists (select 1 from stays where room_id = 'x-lodge');
delete from units where id = 'un-lodge' and not exists (select 1 from rooms where unit_id = 'un-lodge');
delete from properties where id = 'p-lodge' and not exists (select 1 from rooms where property_id = 'p-lodge');

-- ---------- iCal tables ----------
-- One row per extra unit whose calendar Roomboard reads. The feed URL is a secret and is NOT stored here: each row
-- names an Edge Function secret (env_key, e.g. ICAL_MONADH) that ical-sync reads at run time. No secret set yet =
-- "Calendar not linked yet" (linked = false), never an error. Manager can read the status; only the sync writes.
create table if not exists ical_feeds (
  id uuid primary key default gen_random_uuid(),
  room_id text not null unique references rooms on delete cascade,
  label text not null,                      -- where the dates come from, for Donald (e.g. 'SuperControl')
  env_key text not null unique check (env_key ~ '^ICAL_[A-Z0-9_]+$'),
  linked boolean not null default false,
  last_synced_at timestamptz,
  last_error text,
  created_at timestamptz not null default now()
);
insert into ical_feeds (room_id, label, env_key) values
  ('x-pod1', 'Harris calendar', 'ICAL_HARRIS'),
  ('x-pod2', 'Uig calendar', 'ICAL_UIG'),
  ('x-cottage', 'Abhainn Cottage calendar', 'ICAL_ABHAINN'),
  ('x-monadh', 'SuperControl', 'ICAL_MONADH')
  on conflict (room_id) do nothing;
-- Dates taken on another site: dates only, never guest details. Written by ical-sync (service role).
create table if not exists ical_blocks (
  id uuid primary key default gen_random_uuid(),
  feed_id uuid not null references ical_feeds on delete cascade,
  room_id text not null references rooms on delete cascade,
  start_date date not null,
  end_date date not null,                -- exclusive, like stays.departure
  check (end_date > start_date)
);
create index if not exists ical_blocks_room on ical_blocks (room_id, start_date);
-- One secret export link per extra unit (…/functions/v1/ical-export?t=<token>).
create table if not exists ical_exports (
  room_id text primary key references rooms on delete cascade,
  token text not null unique default replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', ''),
  created_at timestamptz not null default now()
);
insert into ical_exports (room_id) select r.id from rooms r join properties p on p.id = r.property_id where not p.contracted
  on conflict (room_id) do nothing;

alter table ical_feeds enable row level security;
alter table ical_blocks enable row level security;
alter table ical_exports enable row level security;
create policy "feeds manager reads" on ical_feeds for select using (my_role() = 'manager');  -- writes: ical-sync only
create policy "blocks read" on ical_blocks for select using (auth.uid() is not null);
create policy "exports manager" on ical_exports for select using (my_role() = 'manager');

-- an extra is one whole unit: "Monadh", not "Monadh Whole lodge"
create or replace function room_label(r text) returns text language sql stable as $$
  select case when p.contracted then p.short_name || ' ' || rm.name else p.name end from rooms rm join properties p on p.id = rm.property_id where rm.id = r $$;

create or replace function is_extra(r text) returns boolean language sql stable security definer set search_path = public as $$
  select not p.contracted from rooms rm join properties p on p.id = rm.property_id where rm.id = r $$;

-- ---------- stays: who may write what ----------
-- Contract rooms: as before (client and manager). Extras: both book directly (no request step). The client reads,
-- changes and cancels only her own extra bookings; others reach her as dates only (extra_taken).
drop policy if exists "stays write" on stays;
drop policy if exists "stays read" on stays;
create policy "stays read" on stays for select using (
  my_role() in ('manager', 'cleaner') or (my_role() = 'client' and (not is_extra(room_id) or booked_by = auth.uid())));
create policy "stays manager" on stays for all using (my_role() = 'manager') with check (my_role() = 'manager');
create policy "stays client contract" on stays for all using (my_role() = 'client' and not is_extra(room_id))
  with check (my_role() = 'client' and not is_extra(room_id));
create policy "stays client extra" on stays for all using (my_role() = 'client' and is_extra(room_id) and booked_by = auth.uid())
  with check (my_role() = 'client' and is_extra(room_id) and booked_by = auth.uid());

-- Taken dates in the extras without who (Sheena cannot read other guests' rows).
create or replace function extra_taken() returns table (room_id text, start_date date, end_date date)
language sql stable security definer set search_path = public as $$
  select s.room_id, s.arrival, coalesce(s.departure, s.arrival + 365) from stays s
  where my_role() = 'client' and is_extra(s.room_id) and s.booked_by is distinct from auth.uid()
    and coalesce(s.departure, 'infinity') > london_today() $$;

-- Runs before stays_before (name order): extras rules, and a clash message that never names another guest.
create or replace function stays_a_extra() returns trigger language plpgsql security definer set search_path = public as $$
declare b ical_blocks;
begin
  if tg_op = 'INSERT' then new.booked_by := coalesce(auth.uid(), new.booked_by); else new.booked_by := old.booked_by; end if;
  if not is_extra(new.room_id) then
    return new;
  end if;
  if my_role() = 'client' then
    if tg_op = 'UPDATE' and old.booked_by is distinct from auth.uid() then
      raise exception 'This booking was made by Donald. Ask him to change it.' using errcode = 'P0001';
    end if;
    -- the clash message never names another guest
    if exists (select 1 from stays s where s.room_id = new.room_id and s.id <> new.id and rb_overlaps(s.arrival, s.departure, new.arrival, new.departure)) then
      raise exception '% is taken on some of those dates. Choose other dates.', room_label(new.room_id) using errcode = 'P0001';
    end if;
  end if;
  if tg_op = 'INSERT' or new.arrival <> old.arrival or new.departure is distinct from old.departure or new.room_id <> old.room_id then
    select * into b from ical_blocks k where k.room_id = new.room_id and rb_overlaps(k.start_date, k.end_date, new.arrival, new.departure) order by start_date limit 1;
    if found then
      raise exception '% is booked elsewhere % → %. Choose other dates.', room_label(new.room_id), b.start_date, b.end_date using errcode = 'P0001';
    end if;
  end if;
  return new;
end $$;
drop trigger if exists stays_a_extra on stays;
create trigger stays_a_extra before insert or update on stays for each row execute function stays_a_extra();

-- ---------- leaving date on an open-ended stay (18 Oct 2026) ----------
-- Same rule as normDep in the app: a leaving date sent with an open status (TBC / until further notice) is a newly
-- set end date, so it becomes 'planned'. stays_before (0002) used to null the date instead, so "set a leaving date"
-- silently did nothing. Switching a dated stay to an open status (date left as it was) still means "make it
-- open-ended": stays_before then clears the date as before. Named to fire first (before stays_a_extra, stays_before).
create or replace function stays_a0_end_date() returns trigger language plpgsql as $$
begin
  if new.dep_status in ('tbc','ufn') and new.departure is not null
     and not (tg_op = 'UPDATE' and old.dep_status not in ('tbc','ufn') and new.departure is not distinct from old.departure)
  then
    new.dep_status := 'planned';
  end if;
  return new;
end $$;
drop trigger if exists stays_a0_end_date on stays;
create trigger stays_a0_end_date before insert or update on stays for each row execute function stays_a0_end_date();

-- ---------- stays_after: extras skip changeovers; booking wording with the indicative price ----------
create or replace function stays_after() returns trigger language plpgsql security definer set search_path = public as $$
declare st stays := coalesce(new, old); msg text; subj text; extra boolean := is_extra(st.room_id); priv boolean;
begin
  if not extra then perform reconcile_room(st.room_id); end if;
  if tg_op = 'UPDATE' and old.room_id <> new.room_id and not is_extra(old.room_id) then perform reconcile_room(old.room_id); end if;
  priv := extra and coalesce((select role::text from profiles where id = st.booked_by), '') <> 'client';
  if extra and tg_op = 'INSERT' then
    subj := 'New booking · ' || room_label(new.room_id);
    msg := 'Booked ' || room_label(new.room_id) || ' (whole property) for ' || stay_label(new) || ' · ' || to_char(new.arrival, 'Dy DD Mon') || ' → '
      || coalesce(to_char(new.departure, 'Dy DD Mon'), 'until further notice') || ' · ' || coalesce(indicative_price(new.room_id, new.arrival, new.departure), 'indicative weekly rate')
      || ' · extra, invoiced separately';
  elsif tg_op = 'INSERT' then
    msg := (case when new.worker_id is null then 'Held ' else 'Booked ' end) || room_label(new.room_id) || ' for ' || stay_label(new) || ' from ' || to_char(new.arrival, 'Dy DD Mon');
    subj := case when new.worker_id is null then 'Room held · ' else 'New arrival · ' end || room_label(new.room_id);
  elsif tg_op = 'DELETE' then
    msg := 'Cancelled ' || stay_label(old) || ' · ' || room_label(old.room_id); subj := 'Stay cancelled · ' || room_label(old.room_id);
  else
    if old.dep_status <> 'confirmed' and new.dep_status = 'confirmed' and old.departure is not distinct from new.departure then
      msg := 'Confirmed departure of ' || stay_label(new) || ' · ' || room_label(new.room_id) || ' on ' || new.departure; subj := 'Departure confirmed · ' || room_label(new.room_id);
    else
      msg := room_label(new.room_id) || ' · ' || stay_label(new) || ': ' || concat_ws(', ',
        case when old.worker_id is null and new.worker_id is not null then 'named hold as ' || stay_label(new) when old.worker_id is distinct from new.worker_id then 'changed guest' end,
        case when old.room_id <> new.room_id then 'moved room' end,
        case when old.arrival <> new.arrival then 'arrival ' || old.arrival || ' → ' || new.arrival end,
        case when old.departure is distinct from new.departure or old.dep_status <> new.dep_status then 'departure ' || coalesce(new.departure::text, new.dep_status::text) end,
        case when old.away_from is distinct from new.away_from or old.away_to is distinct from new.away_to then 'away dates' end,
        case when old.notes is distinct from new.notes then 'notes updated' end);
      subj := 'Stay updated · ' || room_label(new.room_id);
    end if;
  end if;
  -- Donald's own extra bookings stay private: not in Sheena's activity, no alert to her
  if priv then perform log_activity_private(st.room_id, msg, 'stay', st.id::text); return null; end if;
  perform log_activity(st.room_id, msg, 'stay', st.id::text);
  if coalesce(current_setting('rb.bulk', true), '') = 'on' then return null; end if;
  perform alert_stay_change(subj, msg, 'stay:' || st.id || ':' || coalesce(new.version, 0) || ':' || tg_op);
  return null;
end $$;

-- ---------- ical-sync writes here (service role only) ----------
-- Replaces one feed's blocks; logs + alerts Donald once per new clash with a Roomboard booking. Returns new clashes.
-- p_ranges null + p_error null = no secret set for this feed: not linked, so it blocks nothing.
create or replace function replace_ical_blocks(p_feed uuid, p_ranges jsonb, p_error text default null) returns int
language plpgsql security definer set search_path = public as $$
declare f ical_feeds; r jsonb; n int := 0; s record;
begin
  select * into f from ical_feeds where id = p_feed;
  if not found then return 0; end if;
  if p_error is not null then
    update ical_feeds set linked = true, last_error = left(p_error, 300), last_synced_at = now() where id = p_feed;  -- keep the old blocks
    return 0;
  end if;
  if p_ranges is null then
    delete from ical_blocks where feed_id = p_feed;
    update ical_feeds set linked = false, last_error = null, last_synced_at = null where id = p_feed;
    return 0;
  end if;
  delete from ical_blocks where feed_id = p_feed;
  for r in select * from jsonb_array_elements(coalesce(p_ranges, '[]')) loop
    insert into ical_blocks (feed_id, room_id, start_date, end_date) values (p_feed, f.room_id, (r->>'from')::date, (r->>'to')::date);
  end loop;
  update ical_feeds set linked = true, last_error = null, last_synced_at = now() where id = p_feed;
  for s in select st.id, st.arrival, st.departure, k.start_date, k.end_date from stays st join ical_blocks k
      on k.feed_id = p_feed and rb_overlaps(k.start_date, k.end_date, st.arrival, st.departure)
      where st.room_id = f.room_id and coalesce(st.departure, 'infinity') > london_today() loop
    n := n + 1;
    -- Donald only, and no booking-site name in the log
    perform log_activity_private(f.room_id, '⚠ Possible double booking: ' || room_label(f.room_id) || ' is booked on another booking site ' || s.start_date || ' → ' || s.end_date, 'stay', s.id::text);
    perform enqueue_role('manager', '⚠ Possible double booking · ' || room_label(f.room_id),
      room_label(f.room_id) || ' is booked on ' || f.label || ' ' || s.start_date || ' → ' || s.end_date || ', overlapping a Roomboard booking. Check both calendars.',
      'dbl:' || s.id || ':' || p_feed || ':' || s.start_date || ':' || s.end_date);
  end loop;
  return n;
end $$;

-- the sync function only for the service role
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    revoke all on function replace_ical_blocks(uuid, jsonb, text) from public;
    grant execute on function replace_ical_blocks(uuid, jsonb, text) to service_role;
  end if;
end $$;

-- ---------- every 3 hours: read the calendar links (needs pg_cron + pg_net, see 0005) ----------
-- The project URL and service-role key come from Supabase Vault at run time (one-time setup in docs/ACCEPTANCE.md:
-- vault secrets 'project_url' and 'service_role_key'), so nothing secret is written into this migration.
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('ical-sync', '17 */3 * * *', $c$
      select net.http_post(
        (select decrypted_secret from vault.decrypted_secrets where name = 'project_url') || '/functions/v1/ical-sync',
        '{}'::jsonb,
        headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization',
          'Bearer ' || (select decrypted_secret from vault.decrypted_secrets where name = 'service_role_key')))
    $c$);
  end if;
end $$;

-- the board updates live when a calendar is read or the rate changes
alter publication supabase_realtime add table ical_blocks, app_settings;
